/**
 * MASTER NYATA UNIT — diambil dari sheet `ALL GTN` berkas
 * "DATABASE GENTANI BODY, UNIT & ELECTRIC.xlsx" milik AII, BUKAN diketik ulang.
 *
 * Hanya wilayah pabrik UNIT: baris yang produknya TCC, OIL PAN, WP, OP, CSH,
 * TCC/WP, atau yang SLOC tujuannya diawali angka 2. Dari 3.709 baris di sheet
 * itu, 442 masuk wilayah UNIT, 34 dilewati (lihat GENTANI_UNIT_DILEWATI),
 * sisanya menjadi 143 nomor part unik di bawah ini.
 *
 * Sengaja berupa data yang bisa dibaca dan di-review di dalam repo, bukan
 * skrip yang membaca xlsx langsung — sama alasannya dengan data/aiia-master.ts:
 * berkas xlsx itu ada di laptop satu orang, sedangkan berkas ini ikut ke mana
 * pun repo dibawa dan setiap perubahannya terlihat di diff.
 *
 * ── Yang DITURUNKAN, bukan dibaca apa adanya ────────────────────────────────
 *
 * Gentani tidak punya kolom jenis proses maupun SLOC seperti punya kita. Tiga
 * hal di bawah ini hasil penurunan, dan penurunannya tercatat di sini supaya
 * bisa diperiksa — bukan tersembunyi di dalam skrip:
 *
 *   processType  dari P/CODE + SLOC tujuan. P/CODE adalah proses pembuat
 *                (AS assembling, MA machining, DC die casting, DS melting),
 *                sedangkan FG vs WIP ditentukan SLOC tujuannya: 2A000 dan
 *                2B000 adalah gudang barang jadi, 24000 gudang WIP. Buktinya
 *                SELURUH 32 baris yang punya tujuan customer ada di 2A000 atau
 *                2B000, tidak satu pun di 24000.
 *
 *   sloc         dari SLOC Gentani ke lima SLOC blueprint SAP kita:
 *                01000/21000/22000/23000 -> WH80 (komponen & bahan beli),
 *                24000 -> WP80, 2A000/2B000 -> FG80.
 *
 *   uom          dari satuan yang menempel di kolom QTY/BOX ("200 L",
 *                "330 ml", "4 Kg"). Yang bilangan bulat murni berarti pcs.
 *
 * ── Yang TIDAK ada di sini ──────────────────────────────────────────────────
 *
 * Production Version: tidak ada kolomnya di Gentani. Tanpa itu hasil produksi
 * tidak bisa dikirim ke staging SAP — penghalang yang sama seperti sebelumnya,
 * dan berkas ini tidak memecahkannya.
 *
 * BOM: kolom LEVEL di Gentani TIDAK bisa diurai jadi pohon karena urutan
 * induk-anaknya tidak konsisten (di blok TCC induk lebih dulu, di blok CAP
 * justru anak lebih dulu). Rantai antar tahap terbaca dari sufiks nomor part
 * (-02 melting, -04 die casting, -41 heat treatment, tanpa sufiks machining),
 * tetapi memasang BOM dari situ tanpa konfirmasi berarti backflush salah.
 *
 * ── Satu nomor part = satu tahap proses ─────────────────────────────────────
 *
 * AIIA memberi nomor part berbeda untuk setiap tahap. Contoh nyata di data ini:
 *
 *     243131-10490-04  DI02  (Die Casting)        DC AA08 -> 24000
 *     243131-10490-41  DI03  (After Heat Treatm)  KN 7D00137 -> 11000
 *     243131-10490     DI04  (After Torimetron)   FI 0001 -> 2A000
 *
 * Jadi setiap baris di sini adalah SATU part dengan rute SATU langkah, bukan
 * satu part yang melewati tiga proses. Hubungan antar tahap adalah konsumsi
 * BOM, dan itu belum diisi.
 */

export interface PartGentani {
  /** Nomor baris di sheet ALL GTN — supaya tiap baris bisa dilacak ke sumbernya. */
  baris: number;
  partNumber: string;
  name: string;
  backNumber: string | null;
  product: string;
  model: string;
  /** Kedalaman BOM menurut Gentani. Tidak dipakai — lihat catatan di atas. */
  level: string | null;
  /** Kode proses AII: AS, MA, DC, DS, KN (beli), MX (beli tak distok). */
  pcode: string;
  /** Nomor lini untuk proses internal, atau kode supplier untuk KN/MX. */
  lineNo: string;
  supplier: string;
  /** Supplier lain untuk part beli yang sama — satu part boleh beberapa sumber. */
  supplierLain: string[];
  /** Baris lain di sheet dengan nomor part sama. */
  barisLain: number[];
  slocGentani: string | null;
  sloc: string | null;
  processType: string | null;
  sourceType: 'PURCHASED' | 'MANUFACTURED';
  custPartNo: string | null;
  destCustomer: string | null;
  destPlant: string | null;
  qtyPerBox: number | null;
  /** Isi asli kolom QTY/BOX bila bukan bilangan bulat, mis. "490-580 Kg". */
  qtyBoxRaw: string | null;
  uom: string;
  boxType: string | null;
  lastEci: string | null;
  effectiveDate: string | null;
  remark: string | null;
}

